function maxWorkload(workload, k) {
  const n = workload.length;
  const NEG = -1e15;
  const noBoost = Array.from({ length: n }, () => Array(k+1).fill(NEG));
  const boost = Array.from({ length: n }, () => Array(k+1).fill(NEG));
  noBoost[0][0] = workload[0];
  if (k >= 1) boost[0][1] = 2 * workload[0];
  for (let i = 1; i < n; i++) {
    for (let t = 0; t <= k; t++) {
      noBoost[i][t] = Math.max(noBoost[i-1][t], boost[i-1][t]) + workload[i];
    }
    for (let t = 1; t <= k; t++) {
      if (noBoost[i-1][t-1] > NEG) boost[i][t] = noBoost[i-1][t-1] + 2*workload[i];
    }
  }
  let best = NEG, bestT = 0, bestS = 0;
  for (let t = 0; t <= k; t++) {
    if (noBoost[n-1][t] > best) { best = noBoost[n-1][t]; bestT = t; bestS = 0; }
    if (boost[n-1][t] > best) { best = boost[n-1][t]; bestT = t; bestS = 1; }
  }
  // reconstruction would backtrack using saved states (omitted for brevity)
  return { maxValue: best, boostedIndices: [] };
}
```

## Why This Is Asked
Tests 1D partition DP, median-based block costs, and reconstruction; mirrors realistic facility placement.

## Key Concepts
- DP over partitions
- Median-based block cost
- Prefix sums for O(1) block cost
- Backpointer reconstruction
- Time/space trade-offs and potential optimizations

## Code Example
```javascript
function minPostOffice(X, k) {
  const n = X.length;
  const cost = Array.from({length: n}, () => Array(n).fill(0));

  // Precompute prefix sums for O(1) range sum queries
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + X[i];
  }

  // Precompute block costs using median property
  for (let l = 0; l < n; l++) {
    for (let r = l; r < n; r++) {
      const m = Math.floor((l + r) / 2);
      cost[l][r] = (X[m] * (m - l) - (prefix[m] - prefix[l])) +
                   ((prefix[r + 1] - prefix[m + 1]) - X[m] * (r - m));
    }
  }

  // DP table and backpointers
  const dp = Array.from({length: n + 1}, () => Array(k + 1).fill(Infinity));
  const parent = Array.from({length: n + 1}, () => Array(k + 1).fill(-1));
  dp[0][0] = 0;

  for (let p = 1; p <= k; p++) {
    for (let i = 1; i <= n; i++) {
      for (let j = p - 1; j < i; j++) {
        const candidate = dp[j][p - 1] + cost[j][i - 1];
        if (candidate < dp[i][p]) {
          dp[i][p] = candidate;
          parent[i][p] = j;
        }
      }
    }
  }

  // Reconstruct solution
  const blocks = [];
  let curr = n;
  for (let p = k; p >= 1; p--) {
    const start = parent[curr][p];
    blocks.unshift([start, curr - 1]);
    curr = start;
  }

  return { cost: dp[n][k], blocks };
}
```

## Complexity Analysis
- Time: O(kn²) for DP transitions plus O(n²) for cost preprocessing
- Space: O(nk) for DP table, reducible to O(n) with layer optimization

## Why This Is Asked
This gauges ability to cast a line-wrapping task into a clear 1D DP with a non-linear line cost and a reconstruction path. It tests handling of last-line quirks and feasibility checks.

## Key Concepts
- 1D DP over word indices; dp[n] = 0 as base.
- Prefix sums to compute line width in O(1) per extension.
- Cost function uses squared unused space; last line excluded.
- Reconstruct solution via next indices.
- Time: O(n^2); Space: O(n).

## Code Example
```javascript
function minWrap(words, W) {
  const n = words.length;
  const pref = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + words[i];
  const dp = new Array(n + 1).fill(Infinity);
  const nxt = new Array(n).fill(-1);
  dp[n] = 0;
  for (let i = n - 1; i >= 0; i--) {
    for (let j = i; j < n; j++) {
      const width = (pref[j + 1] - pref[i]) + (j - i);
      if (width <= W) {
        const cost = (W - width) * (W - width) + dp[j + 1];
        if (cost < dp[i]) { dp[i] = cost; nxt[i] = j + 1; }
      } else break;
    }
  }
  // reconstruction omitted for brevity
  return { minPenalty: dp[0], next: nxt };
}
```

## Follow-up Questions
- How would you modify to penalize the last line as well?
- How would you incorporate tie-breaking to prefer fewer lines?

## Why This Is Asked
Tests budgeted DP on strings and reconstruction. 

## Key Concepts
- dp[i][j][d] encodes a subproblem under a deletion budget; 
- palindrome subsequence logic with matches/skips; 
- reconstruction paths under deletion budget.

## Code Example
```javascript
function maxPalWithDeletions(s, k){
  const n=s.length; 
  const dp=Array.from({length:n},()=>Array.from({length:n},()=>Array(k+1).fill(0)));
  for(let i=0;i<n;i++){ dp[i][i][0]=1; for(let d=1; d<=k; d++) dp[i][i][d]=1; }
  for(let len=2; len<=n; len++){
    for(let i=0; i+len-1<n; i++){
      const j=i+len-1;
      for(let d=0; d<=k; d++){
        if(s[i]===s[j]){
          dp[i][j][d]=Math.max(dp[i+1][j-1][d]+2, (d>0?dp[i+1][j][d-1]:0), (d>0?dp[i][j-1][d-1]:0));
        } else {
          dp[i][j][d]=Math.max(dp[i+1][j][d], dp[i][j-1][d], (d>0?dp[i+1][j-1][d-1]:0));
        }
      }
    }
  }
  return Math.max(...Array.from({length:k+1},(_,d)=>dp[0][n-1][d]));
}
```

